    // Imports the simulated hardware to NI Max for running the example
    await ts.callVi(
      'Common\\Import Hardware Config.vi',
      inputs: {'Configuration file': locals.hardwareConfigPath},
    ); // Import Hardware Config

    // Example 1 - Demonstrates extraction of tones (Frequency domain measurement) from the captured Audio Signal (Single tone sine wave)
    // Audio Test with Single Tone Signals
