    //
    //
    // Example 2 - Demonstrates extraction of tones (Frequency domain measurement) from the captured Multi tone Audio Signal
    // Audio Test with Multi Tone Signals
    await audioFilterCheck(); // Audio Filter Check
  } finally {
    // Turn off all configured AO channels by configuring to 0V
    await turnOffAllAoChannels(); // Power down all AO Channels
  }
}

